import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Sequence } from '../remotionShim';
import { Rect, Circle } from "@remotion/shapes";
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type JesusCourageProps = Record<string, any>;

const JesusCourage: React.FC<JesusCourageProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 12,
  primaryColor = "#F5F5F0",
  secondaryColor = "#8B0000",
  accentColor = "#D4AF37",
  titleText = "Jesus' suffering gives us courage",
  subtitleText = "All that He went through for us...",
  closingText = "What do we have to be afraid of?",
  crossOpacity = 0.3,
}) => {
  useFontLoader(["Cinzel", "Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Utilities
  const fadeIn = (start: number) => interpolate(frame, [start, start + 30], [0, 1], { extrapolateRight: "clamp" });
  const slideUp = (start: number) => interpolate(frame, [start, start + 45], [50, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  
  // Cross Animation
  const crossEntrance = spring({
    frame: frame - 15,
    fps,
    config: { damping: 200, stiffness: 50 }
  });

  // Background Particles (Subtle floating lights)
  const particles = new Array(12).fill(0).map((_, i) => {
    const xSeed = (i * 9123) % width;
    const ySeed = (i * 8123) % height;
    const size = 2 + (i % 4);
    const floatY = interpolate(frame, [0, durationInSeconds * fps], [0, -100 - (i * 10)]);
    const opacity = interpolate(Math.sin(frame / 60 + i), [-1, 1], [0.1, 0.4]);
    return (
      <Circle
        key={i}
        radius={size}
        fill={primaryColor}
        style={{
          position: "absolute",
          left: xSeed,
          top: ySeed,
          opacity,
          transform: `translateY(${floatY}px)`
        }}
      />
    );
  });

  // Layout Calculations
  const centerX = width / 2;
  const centerY = height / 2;
  const crossThickness = width * 0.02;
  const crossHeight = height * 0.6;
  const crossWidth = width * 0.35;

  // Timings
  const titleStart = 45;
  const subStart = 110;
  const closingStart = 200;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Background Layer */}
      <AbsoluteFill>
        {particles}
        {/* Vignette */}
        <div style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background: `radial-gradient(circle at center, transparent 0%, ${backgroundColor} 90%)`,
          opacity: 0.8
        }} />
      </AbsoluteFill>

      {/* Central Cross Graphic */}
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", opacity: crossOpacity }}>
         <div style={{ position: "relative" }}>
             {/* Vertical Beam */}
            <Rect 
                width={crossThickness} 
                height={crossHeight * crossEntrance}
                fill={secondaryColor}
                style={{
                   position: "absolute",
                   left: -crossThickness / 2,
                   top: -crossHeight * 0.4,
                   transformOrigin: "top center",
                   boxShadow: `0 0 40px ${secondaryColor}66`
                }}
            />
            {/* Horizontal Beam */}
             <Rect 
                width={crossWidth * crossEntrance} 
                height={crossThickness}
                fill={secondaryColor}
                style={{
                   position: "absolute",
                   left: (-crossWidth * crossEntrance) / 2,
                   top: crossHeight * 0.1, // Positioning the cross bar slightly up
                   transformOrigin: "center left",
                   boxShadow: `0 0 40px ${secondaryColor}66`
                }}
            />
         </div>
      </AbsoluteFill>

      {/* Text Content Layer */}
      <AbsoluteFill style={{ 
          justifyContent: "center", 
          alignItems: "center", 
          flexDirection: "column",
          gap: 40,
          padding: "0 10%" 
        }}>
        
        {/* Title */}
        <div style={{
            opacity: fadeIn(titleStart),
            transform: `translateY(${slideUp(titleStart)}px)`,
            fontFamily: "Cinzel",
            fontSize: 72,
            fontWeight: 700,
            color: primaryColor,
            textAlign: "center",
            textShadow: `0 4px 20px ${backgroundColor}`,
            zIndex: 10
        }}>
            {titleText}
        </div>

        {/* Divider Line */}
        <div style={{
            width: interpolate(frame, [titleStart + 20, titleStart + 60], [0, 200], { extrapolateRight: "clamp" }),
            height: 2,
            backgroundColor: accentColor,
            opacity: fadeIn(titleStart + 20),
            borderRadius: 2
        }}/>

        {/* Subtitle */}
        <div style={{
            opacity: fadeIn(subStart),
            transform: `translateY(${slideUp(subStart)}px)`,
            fontFamily: "Montserrat",
            fontSize: 42,
            fontWeight: 400,
            color: primaryColor,
            textAlign: "center",
            maxWidth: width * 0.7,
            lineHeight: 1.5,
            zIndex: 10
        }}>
            {subtitleText}
        </div>

        {/* Closing Question */}
        <div style={{
            marginTop: 60,
            opacity: fadeIn(closingStart),
            transform: `translateY(${slideUp(closingStart)}px)`,
            fontFamily: "Cinzel",
            fontSize: 56,
            fontWeight: 600,
            color: accentColor,
            textAlign: "center",
            zIndex: 10,
            letterSpacing: "0.05em"
        }}>
            {closingText}
        </div>

      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default JesusCourage;